WITH base AS (SELECT id, product_id, sale_date, units, revenue, ADD_MONTHS(sale_date, 3) AS sale_date_plus_months FROM store_sales WHERE sale_date > TO_DATE('2023-07-28')) SELECT d.brand, d.category, COUNT(*) AS num_rows, AVG(src.revenue) AS avg_revenue, ROUND(AVG(src.units), 2) AS avg_units, GROUPING_ID() AS grouping_level FROM base src INNER JOIN products d ON src.product_id = d.id GROUP BY GROUPING SETS ((d.brand, d.category), (d.brand)) ORDER BY num_rows DESC NULLS FIRST
